    "ref/status": {"fields":{"annotation_vcf":{"about":"Custom annotation VCF path to include in readiness checks.","default":null,"flag":["--annotation-vcf"],"nullable":true,"path":true,"type":"string"},"dataset_library":{"about":"Dataset library folder for the test genome (default: config dataset_library, else ``datasets`` beside the reference library).","default":null,"flag":["--genome-library"],"nullable":true,"path":true,"type":"string"},"input":{"about":"A BAM/CRAM or VCF whose build picks the annotation files to report.","default":null,"flag":["--input"],"nullable":true,"path":true,"type":"string"},"ref":{"about":"Reference library folder, or a FASTA in it (default: config reference_library, else reference_fasta's library, else the default library).","default":null,"flag":["--ref"],"nullable":true,"path":true,"type":"string"}},"required":[],"summary":"What the reference library holds, as the result's `details`: genomes and their indexes, annotation data, gene maps, VEP cache, PharmCAT, ploidy and mappability files, and the test genome."},
