    "repair/ftdna-bam": {"fields":{"input":{"about":"The FTDNA BAM or CRAM to repair.","flag":["--input"],"path":true,"type":"string"},"outdir":{"about":"Folder for the outputs (default: config output_directory, else the input's folder).","default":null,"flag":["--outdir"],"nullable":true,"path":true,"type":"string"},"output":{"about":"Repaired BAM to write (default: <outdir>/<input stem>_repaired.bam); not the input itself.","default":null,"flag":["--output"],"nullable":true,"path":true,"type":"string"},"ref":{"about":"Reference FASTA or reference library folder; resolved from the input's header when omitted (default: config reference_fasta).","default":null,"flag":["--ref"],"nullable":true,"path":true,"type":"string"}},"required":["input"],"summary":"Copy an FTDNA BAM or CRAM to a BAM whose read names have no spaces (`FTDNA read 7` becomes `FTDNA:read:7`), so GATK and other tools accept it."},
