    "sample/show": {"fields":{"input":{"about":"BAM, CRAM or VCF of the sample; its folder is the workspace unless workspace is given, and its facts are shown.","default":null,"nullable":true,"path":true,"type":"string"},"workspace":{"about":"Sample folder holding wgsextract.sample.toml (default: the --genome folder, else the --input's folder).","default":null,"nullable":true,"path":true,"type":"string"}},"required":[],"summary":"Show a sample's overrides, the facts recorded for each of its files and the result manifests indexed in its workspace."},
