    "score/pgs": {"fields":{"build":{"about":"Input/scoring coordinate build (must match).","enum":["GRCh37","GRCh38"],"flag":["--build"],"type":"string"},"confident_bed":{"about":"Same-sample/build confident BED: absent SNPs within it are reference calls (needs --ref).","default":null,"flag":["--confident-bed"],"nullable":true,"path":true,"type":"string"},"input":{"about":"Single-sample VCF/gVCF, or choose --sample.","flag":["--input"],"path":true,"type":"string"},"keep_ambiguous":{"about":"Keep A/T and C/G SNPs only if their forward strand was independently verified.","default":null,"flag":["--keep-ambiguous","--no-keep-ambiguous"],"nullable":true,"type":"boolean"},"min_match":{"about":"Minimum matched fraction for percentile eligibility (default 0.75).","default":null,"flag":["--min-match"],"nullable":true,"type":"number"},"outdir":{"about":"Folder for the outputs (default: config output_directory, else the input's folder).","default":null,"flag":["--outdir"],"nullable":true,"path":true,"type":"string"},"pgs_id":{"about":"Catalog PGS ID; uncurated IDs carry a warning.","default":null,"flag":["--pgs-id"],"nullable":true,"type":"string"},"plink2_check":{"about":"Cross-check the matched-set sum with installed plink2 (no imputation).","default":false,"flag":["--plink2-check"],"type":"boolean"},"ref":{"about":"Indexed reference FASTA, for confident BED/gVCF reference calls.","default":null,"flag":["--ref"],"nullable":true,"path":true,"type":"string"},"sample":{"about":"VCF sample name (required for multi-sample files).","default":null,"flag":["--sample"],"nullable":true,"type":"string"},"scoring_file":{"about":"Own scoring TSV[.gz], overriding Catalog selection.","default":null,"flag":["--scoring-file"],"nullable":true,"path":true,"type":"string"},"trait":{"about":"Curated trait (see docs/pgs.md).","default":null,"flag":["--trait"],"nullable":true,"type":"string"}},"required":["input","build"],"summary":"Score one sample's VCF on the specified build."},
    "sign/create": {"fields":{"outdir":{"about":"Folder for the outputs (default: config output_directory, else the inputs' common folder).","default":null,"flag":["--outdir"],"nullable":true,"path":true,"type":"string"},"output":{"about":"Manifest path.","default":null,"flag":["--output"],"nullable":true,"path":true,"type":"string"},"paths":{"about":"Files, or folders whose files (recursively) to list.","flag":[],"items":"string","type":"array"},"threads":{"about":"CPU threads; None picks a count for this machine (default: config cpu_threads, else auto).","default":null,"flag":["--threads"],"nullable":true,"type":"integer"}},"required":["paths"],"summary":"Write a checksum manifest of `paths`, signed when a key is given."},
