    "typing/str": {"fields":{"caller":{"about":"Repeat caller (default: longtr for Nanopore and PacBio reads, expansionhunter for others).","default":null,"enum":["expansionhunter","longtr","strkit"],"flag":["--caller"],"nullable":true,"type":"string"},"catalog":{"about":"Repeat catalog in the caller's format: an ExpansionHunter variant catalog (JSON) or a LongTR or STRkit BED.","default":null,"flag":["--catalog"],"nullable":true,"path":true,"type":"string"},"input":{"about":"Indexed BAM or CRAM aligned to GRCh37/hg19 or GRCh38.","flag":["--input"],"path":true,"type":"string"},"outdir":{"about":"Folder for the outputs (default: config output_directory, else the input's folder).","default":null,"flag":["--outdir"],"nullable":true,"path":true,"type":"string"},"ref":{"about":"Reference FASTA or reference library folder; resolved from the input's header when omitted (default: config reference_fasta).","default":null,"flag":["--ref"],"nullable":true,"path":true,"type":"string"},"sex":{"about":"Sample sex (the number of chrX alleles).","default":null,"enum":["male","female"],"flag":["--sex"],"nullable":true,"type":"string"},"threads":{"about":"CPU threads; None picks a count for this machine (default: config cpu_threads, else auto).","default":null,"flag":["--threads"],"nullable":true,"type":"integer"}},"required":["input"],"summary":"Size disease short tandem repeats (HTT, FMR1, C9ORF72, ...) and flag those outside the normal range, with ExpansionHunter for short reads and LongTR (or STRkit) for Nanopore and PacBio; not a diagnosis."},
