    "vcf/cadd": {"fields":{"cadd_file":{"about":"Path to the CADD whole-genome SNV TSV (cadd_<build>.tsv.gz).","default":null,"flag":["--cadd-file"],"nullable":true,"path":true,"type":"string"},"cadd_indel_file":{"about":"Path to a CADD indel TSV (cadd_indel_<build>.tsv.gz); used when present.","default":null,"flag":["--cadd-indel-file"],"nullable":true,"path":true,"type":"string"},"input":{"about":"The VCF to read when ``vcf_input`` is unset.","default":null,"flag":["--input"],"nullable":true,"path":true,"type":"string"},"min_score":{"about":"Also write the calls with a CADD PHRED score of at least this.","default":null,"flag":["--min-score"],"nullable":true,"type":"number"},"outdir":{"about":"Folder for the outputs (default: config output_directory, else the VCF's folder).","default":null,"flag":["--outdir"],"nullable":true,"path":true,"type":"string"},"ref":{"about":"Reference FASTA or reference library folder; resolved from the input's header when omitted (default: config reference_fasta).","default":null,"flag":["--ref"],"nullable":true,"path":true,"type":"string"},"threads":{"about":"CPU threads; None picks a count for this machine (default: config cpu_threads, else auto).","default":null,"flag":["--threads"],"nullable":true,"type":"integer"},"vcf_input":{"about":"The VCF to read; wins over ``input``.","default":null,"flag":["--vcf-input"],"nullable":true,"path":true,"type":"string"}},"required":[],"summary":"CADD deleteriousness scores (CADD_RAW, CADD_PHRED) as `cadd_annotated.vcf.gz`."},
